INSERT INTO settings (key, value) VALUES ('about_short', 'Founded by Mr. Tinashe Changweya, Fumati grew from a determined local team into one of Zimbabwe''s most respected engineering brands. We design, fabricate and erect — from stadium roofs and bridges to mining equipment — all from our own workshop in Waterfalls, Harare.') ON CONFLICT (key) DO NOTHING;
INSERT INTO settings (key, value) VALUES ('about_long', 'Fumati Engineers (Fumati Group t/a Fumati Engineering) is a multi-award-winning engineering company based in Waterfalls, Harare, specialising in structural engineering, mechanical engineering, steel fabrication, plant fitting, and equipment production and services.
INSERT INTO settings (key, value) VALUES ('mission', 'To deliver world-class structural, mechanical and fabrication engineering that turns our clients'' ambitions into lasting steel — safely, on time and to the highest standard.') ON CONFLICT (key) DO NOTHING;
INSERT INTO settings (key, value) VALUES ('vision', 'To be Africa''s most trusted engineering and fabrication company, proudly built in Zimbabwe.') ON CONFLICT (key) DO NOTHING;
