INSERT INTO settings (key, value) VALUES ('ceo_bio', 'Tinashe founded Fumati Engineers with one conviction: Zimbabwe''s infrastructure can be built by Zimbabweans, to world standards. Under his leadership Fumati has grown from a small fabrication team into a multi-award-winning engineering company trusted with stadiums, bridges and industrial structures.') ON CONFLICT (key) DO NOTHING;
