INSERT INTO services (title, short, body, bullets, image, position) VALUES ('Structural Engineering', 'Analysis, design and erection of steel structures that carry real load — from portal frames to multi-storey buildings.', 'Our engineers design and erect commercial and industrial steel structures, large-span roof trusses, terraces and grandstands, and steel bridge elements. Every member is checked, fabricated in our own workshop and erected by our own crews.', 'Commercial & industrial steel structures
INSERT INTO services (title, short, body, bullets, image, position) VALUES ('Mechanical Engineering', 'Heavy machinery, conveyors and plant that keep industry and mining moving.', 'From installing heavy machinery to maintaining whole plants, we keep production running with planned maintenance contracts and rapid breakdown response.', 'Heavy machinery installation
INSERT INTO services (title, short, body, bullets, image, position) VALUES ('Steel Fabrication & Welding', 'Precision cutting, welding and custom components from our own Harare workshop.', 'Our Waterfalls workshop turns raw steel into structural beams, trusses, railings, frames and one-off components, with quality checks at every stage.', 'Custom steel components
INSERT INTO services (title, short, body, bullets, image, position) VALUES ('Plant Fitting', 'Installation, alignment and commissioning of industrial and mining plant.', 'We install, align and commission plant for mines, factories and processing facilities, and stay on for handover and training.', 'Plant installation
INSERT INTO services (title, short, body, bullets, image, position) VALUES ('Equipment Production', 'Mining, agricultural and commercial equipment — even double-deck boats.', 'If it is made of steel, we can build it: mining equipment, agricultural tools, food-trade containers, fryer stands and custom vessels.', 'Mining equipment
INSERT INTO services (title, short, body, bullets, image, position) VALUES ('General Construction', 'Turnkey builds from foundation to handover — stadiums, schools, churches and shops.', 'Our construction teams handle groundworks, foundations, blockwork and finishes, so steel and civil works run as one programme under one contract.', 'Foundations and groundworks
INSERT INTO services (title, short, body, bullets, image, position) VALUES ('Gates, Doors & Architectural Metalwork', 'Gates, frames and steel-and-glass that make an entrance.', 'Classic and sliding gates, garage doors, frames, glass-and-steel facades and signage — designed and fabricated to last.', 'Classic and sliding gates
INSERT INTO services (title, short, body, bullets, image, position) VALUES ('Hardware & Steel Products', 'Tank stands, steel furniture and frames at our Simon Mazorodze Road hardware shop.', 'Walk in to our hardware shop for ready-made steel products, or order to size.', 'Tank stands
INSERT INTO team (name, role, department, bio, photo, email, linkedin, position) VALUES ('Mr. Tinashe Changweya', 'CEO & Founder', 'Leadership', 'Founder and driving force of Fumati Engineers. Award-winning businessman leading Fumati''s mission to build Zimbabwe with local talent and global standards.', '/images/tinashe-changweya-award.webp', '', '', 1);
