INSERT INTO faqs (question, answer, position) VALUES ('Where is Fumati Engineers located?', 'Our head office and fabrication workshop are at 1/5 Sherwood Crescent, Waterfalls, Harare. Our hardware shop is on Simon Mazorodze Road, Harare.', 1);
INSERT INTO faqs (question, answer, position) VALUES ('Do you work outside Harare?', 'Yes. We deliver projects across Zimbabwe — stadiums, bridges, mines, farms and commercial sites — and can discuss work beyond our borders.', 2);
INSERT INTO faqs (question, answer, position) VALUES ('What kind of steel structures do you build?', 'Portal frames, warehouses, multi-storey steel frames, large-span roof trusses, terraces and grandstands, canopies, bridges and glass-and-steel facades.', 3);
INSERT INTO faqs (question, answer, position) VALUES ('Can you design as well as fabricate and install?', 'Yes. We handle design (CAD/3D), fabrication in our own workshop and installation by our own crews, so you deal with one accountable team.', 4);
INSERT INTO faqs (question, answer, position) VALUES ('How do I get a quotation?', 'Send us your drawings or a description through the quote form or WhatsApp. We usually respond within 24 hours and can arrange a site visit.', 5);
INSERT INTO faqs (question, answer, position) VALUES ('Do you make gates, doors and steel furniture?', 'Yes — classic and sliding gates, garage doors, door and window frames, tank stands, steel beds and more, made to order or from our hardware shop.', 6);
INSERT INTO projects (slug, title, category, location, year, client, status, summary, body, scope, challenge, solution, result, cover, cover_alt, featured, published, position) VALUES ('the-heart-stadium', 'The Heart Stadium', 'Stadiums & Landmarks', 'Waterfalls, Harare', '', '', 'Completed', 'Structural steel terraces, roof canopies and the landmark entrance gate and banner metalworks.', 'Fumati delivered the structural steelwork for The Heart Stadium in Waterfalls, Harare — terrace steel, roof canopies over the stands and the signature entrance gate and banner. Steel was fabricated in our nearby Waterfalls workshop and erected by our own crews, including crane-lifted installation of the arched entrance banner.', 'Terrace structural steel
